INSERT IGNORE INTO dialogues (dialogue, movie, aliases, source_url) VALUES
('Nee po mone Dinesha!', 'Narasimham', JSON_ARRAY('Narasimham', 'നരസിംഹം'), 'https://www.cinemaexpress.com/malayalam/news/2026/Mar/12/mohanlal-philosophises-po-mone-dinesha-line-from-narasimham'),
('Shammi hero aada, hero!', 'Kumbalangi Nights', JSON_ARRAY('Kumbalangi Nights', 'Kumbalangi Night', 'കുമ്പളങ്ങി നൈറ്റ്സ്'), 'https://www.thenewsminute.com/article/shammi-hero-da-hero-mohammed-shami-uses-kumbalangi-nights-dialogue-viral-video-117211'),
('Polandine patti oraksharam mindaruthu!', 'Sandesham', JSON_ARRAY('Sandesham', 'Sandhesham', 'സന്ദേശം'), 'https://www.reddit.com/r/MalayalamMovies/comments/ting1a/'),
('Lelu allu, lelu allu!', 'Thenmavin Kombath', JSON_ARRAY('Thenmavin Kombath', 'Thenmavin Kombathu', 'Thenmaavin Kombathu', 'Thenmaavin Kombath', 'തേന്മാവിൻ കൊമ്പത്ത്'), 'https://www.reddit.com/r/Kerala/comments/xc85gr/');
INSERT IGNORE INTO movie_puzzles (movie, aliases, clues) VALUES
('Drishyam', JSON_ARRAY('Drishyam', 'ദൃശ്യം'), JSON_ARRAY('A family faces a crisis that threatens its ordinary life.', 'The story takes place in a village in Kerala.', 'The father runs a cable television business and loves movies.', 'A disappearance leads to a police investigation into Georgekutty and his family.', 'Mohanlal plays Georgekutty in this 2013 thriller directed by Jeethu Joseph.')),
('Manichitrathazhu', JSON_ARRAY('Manichitrathazhu', 'Manichithrathazhu', 'മണിച്ചിത്രത്താഴ്'), JSON_ARRAY('A family home becomes the setting for mysterious events.', 'An old legend about a dancer hangs over the household.', 'A couple named Ganga and Nakulan move into the ancestral house.', 'Dr. Sunny investigates Ganga’s connection to Nagavalli.', 'Shobana, Mohanlal and Suresh Gopi star in this 1993 psychological thriller directed by Fazil.')),
('Minnal Murali', JSON_ARRAY('Minnal Murali', 'മിന്നൽ മുരളി'), JSON_ARRAY('Two ordinary people discover extraordinary abilities.', 'The story is set in the fictional village of Kurukkanmoola.', 'A lightning strike changes the lives of both men.', 'Jaison is a tailor, while Shibu works at a tea shop.', 'Tovino Thomas plays the superhero in this 2021 film directed by Basil Joseph.'));
